import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "", address: "" });
  // энд бичнэ үү: хоосон талбаруудын тоог filter-ээр тоол
  const errors = 0;
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <TextInput nativeID="address" style={styles.input} placeholder="Хаяг"
        value={form.address} onChangeText={(v) => setForm({ ...form, address: v })} />
      <Text nativeID="count" style={styles.count}>Дутуу талбар: {errors}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  count: { fontSize: 16, fontWeight: "600", color: "#dc2626" },
});

registerRootComponent(App);

import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "", address: "" });
  const errors = [form.name, form.phone, form.address].filter((v) => v.trim() === "").length;
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <TextInput nativeID="address" style={styles.input} placeholder="Хаяг"
        value={form.address} onChangeText={(v) => setForm({ ...form, address: v })} />
      <Text nativeID="count" style={styles.count}>Дутуу талбар: {errors}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  count: { fontSize: 16, fontWeight: "600", color: "#dc2626" },
});

registerRootComponent(App);
